import argparse, json, os
def main():
    # All child model/encoder helpers inherit this; update ownership manifests
    # remain exact without accumulating generated bytecode in the application.
    import sys
    sys.dont_write_bytecode=True
    os.environ['PYTHONDONTWRITEBYTECODE']='1'
    p=argparse.ArgumentParser("界渡"); sub=p.add_subparsers(dest="cmd",required=True)
    s=sub.add_parser("sync"); s.add_argument("--force",action="store_true")
    q=sub.add_parser("search"); q.add_argument("query"); q.add_argument("--mode",choices=["keyword","vector","hybrid"],default="hybrid")
    sub.add_parser("status"); mcp=sub.add_parser("mcp")
    mcp.add_argument('--transport',choices=['stdio','localhost_http'])
    for role in ("console", "watch"):
        service = sub.add_parser(role)
        service.add_argument("--launch-id")
        service.add_argument("--vault")
        service.add_argument("--local-data")
        service.add_argument("--isolated-test", action="store_true")
        service.add_argument("--test-owner-seconds", type=int)
        service.add_argument("--model-precision", choices=["fp32","fp16"])
        service.add_argument("--embedding-batch-size", type=int)
        service.add_argument("--embedding-duty-cycle", type=float)
    a=p.parse_args()
    os.environ["KNOWLEDGE_BRIDGE_PROCESS_ROLE"] = a.cmd
    if a.cmd in {"console", "watch"} and a.launch_id:
        import sys
        from pathlib import Path
        os.environ["KNOWLEDGE_BRIDGE_LAUNCH_ID"] = a.launch_id
        if a.isolated_test: os.environ["KNOWLEDGE_BRIDGE_PROTECTION_TEST_MODE"] = "1"
        if a.isolated_test and a.test_owner_seconds is not None:
            os.environ['KNOWLEDGE_BRIDGE_OWNER_SESSION_SECONDS'] = str(max(1,min(3600,a.test_owner_seconds)))
        if a.model_precision:os.environ['KNOWLEDGE_BRIDGE_MODEL_PRECISION']=a.model_precision
        if a.embedding_batch_size is not None:
            if not 1<=a.embedding_batch_size<=128:raise ValueError('embedding batch size 必须在 1 到 128 之间')
            os.environ['KNOWLEDGE_BRIDGE_EMBEDDING_BATCH_SIZE']=str(a.embedding_batch_size)
        if a.embedding_duty_cycle is not None:
            if not .1<=a.embedding_duty_cycle<=1:raise ValueError('embedding duty cycle 必须在 0.1 到 1.0 之间')
            os.environ['KNOWLEDGE_BRIDGE_EMBEDDING_DUTY_CYCLE']=str(a.embedding_duty_cycle)
        if a.vault and a.local_data:
            os.environ["KNOWLEDGE_BRIDGE_VAULT"] = str(Path(a.vault).resolve())
            os.environ["KNOWLEDGE_BRIDGE_LOCAL_DATA"] = str(Path(a.local_data).resolve())
            log_path = Path(a.local_data) / "runtime" / "bridge-launcher.log"
            log_path.parent.mkdir(parents=True, exist_ok=True)
            sys.stdout = sys.stderr = log_path.open("a", encoding="utf-8", buffering=1)
        from .process_runtime import publish_process
        publish_process(a.cmd)
    from .core import sync, search, overview
    if a.cmd=="sync": print(json.dumps(sync(a.force,operation="cli_rebuild" if a.force else "cli_sync"),ensure_ascii=False,indent=2))
    elif a.cmd=="search": print(json.dumps(search(a.query,a.mode),ensure_ascii=False,indent=2))
    elif a.cmd=="status": print(json.dumps(overview(),ensure_ascii=False,indent=2))
    elif a.cmd=="console":
        import uvicorn; from .web import app; from .bridge_settings import load_settings,validate_settings
        settings=load_settings(); validate_settings(settings)
        import threading
        from .update_quiesce import monitor_shutdown, acknowledge_shutdown
        from .workspace import LOCAL_DATA_ROOT
        server=uvicorn.Server(uvicorn.Config(app,host=settings["console"]["host"],port=settings["console"]["port"],proxy_headers=False))
        stopped=threading.Event();accepted=[]
        def watch_update():
            row=monitor_shutdown(LOCAL_DATA_ROOT,os.environ.get('KNOWLEDGE_BRIDGE_LAUNCH_ID'),
                'console',lambda:setattr(server,'should_exit',True),stopped)
            if row:accepted.append(row)
        monitor=threading.Thread(target=watch_update,daemon=True,name='update-console-exit');monitor.start()
        try:server.run()
        finally:stopped.set();monitor.join(timeout=1)
        if accepted:acknowledge_shutdown(LOCAL_DATA_ROOT,accepted[0],'console')
    elif a.cmd=="watch":
        import threading
        from .watcher import run
        from .update_quiesce import monitor_shutdown, acknowledge_shutdown
        from .workspace import LOCAL_DATA_ROOT
        stop=threading.Event();done=threading.Event();accepted=[]
        def watch_update():
            row=monitor_shutdown(LOCAL_DATA_ROOT,os.environ.get('KNOWLEDGE_BRIDGE_LAUNCH_ID'),'watch',stop.set,done)
            if row:accepted.append(row)
        monitor=threading.Thread(target=watch_update,daemon=True,name='update-watcher-exit');monitor.start()
        try:run(stop)
        finally:done.set();monitor.join(timeout=1)
        if accepted:acknowledge_shutdown(LOCAL_DATA_ROOT,accepted[0],'watch')
    else:
        from .mcp_server import server
        from .bridge_settings import load_settings,validate_settings
        settings=load_settings(); validate_settings(settings)
        if (a.transport or settings["mcp"]["mode"])=="stdio": server.run()
        else: server.run(transport="streamable-http",host="127.0.0.1",port=settings["mcp"]["port"],streamable_http_path="/mcp")

if __name__=="__main__": main()
